describe('PayPal Payment Method Selection', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should successfully display PayPal payment option and allow selection', () => {
    // Verify PayPal payment option is visible
    cy.get('[data-testid="payment-methods"]').should('be.visible');
    cy.get('[data-testid="paypal-payment-option"]').should('be.visible');

    // Verify PayPal button is clickable
    cy.get('[data-testid="paypal-payment-button"]').should('be.visible');
    cy.get('[data-testid="paypal-payment-button"]').should('have.attr', 'aria-label', 'PayPal');

    // Click PayPal button
    cy.get('[data-testid="paypal-payment-button"]').click();

    // Verify PayPal payment form is displayed
    cy.get('[data-testid="paypal-payment-form"]').should('be.visible');

    // Verify PayPal email field is present
    cy.get('[data-testid="paypal-email-field"]').should('be.visible');
    cy.get('[data-testid="paypal-email-field"]').should('have.value');

    // Verify PayPal button is visible in form
    cy.get('[data-testid="paypal-confirm-button"]').should('be.visible');

    // Verify success message appears
    cy.get('[data-testid="payment-success-message"]').should('be.visible');
    cy.get('[data-testid="payment-success-message"]').should('contain', 'Payment successful');

    // Verify redirect to success page
    cy.url().should('include', '/success');
  });

  it('should handle edge case when PayPal payment fails', () => {
    // Mock PayPal API failure
    cy.intercept('POST', '/api/paypal/payment', {
      statusCode: 500,
      body: { error: 'Payment processing failed' }
    }).as('paypalPaymentFailure');

    // Attempt to select PayPal payment
    cy.get('[data-testid="paypal-payment-button"]').click();

    // Verify error message appears
    cy.get('[data-testid="payment-error-message"]').should('be.visible');
    cy.get('[data-testid="payment-error-message"]').should('contain', 'Payment processing failed');

    // Verify user is not redirected
    cy.url().should('include', '/checkout');

    // Verify user can retry
    cy.get('[data-testid="paypal-payment-button"]').should('be.visible');
    cy.get('[data-testid="paypal-payment-button"]').click();

    // Verify error message disappears and retry button appears
    cy.get('[data-testid="payment-error-message"]').should('not.exist');
    cy.get('[data-testid="retry-payment-button"]').should('be.visible');

    // Verify retry button is clickable
    cy.get('[data-testid="retry-payment-button"]').should('be.visible');
    cy.get('[data-testid="retry-payment-button"]').click();

    // Verify PayPal payment form is displayed again
    cy.get('[data-testid="paypal-payment-form"]').should('be.visible');

    // Verify PayPal button is visible in form
    cy.get('[data-testid="paypal-payment-button"]').should('be.visible');

    // Verify success message appears after successful retry
    cy.get('[data-testid="payment-success-message"]').should('be.visible');
    cy.get('[data-testid="payment-success-message"]').should('contain', 'Payment successful');

    // Verify redirect to success page
    cy.url().should('include', '/success');
  });
});
